return new Promise((resolve, reject) => {
  const exportCanvas = () => {
    uni.canvasToTempFilePath(
      {
        canvasId,
        x: 0,
        y: 0,
        width,
        height,
        destWidth: width,
        destHeight: height,
        fileType: 'jpg',
        quality: 0.9,
        success: (res) => {
          const out = res.tempFilePath
          // #ifdef H5
          tempOutputToFile(out)
            .then((file) => resolve({ file }))
            .catch(reject)
          // #endif
          // #ifndef H5
          resolve({ filePath: out })
          // #endif
        },
        fail: reject,
      },
      component
    )
  }
  ctx.draw(false, () => {
    // H5 需等一帧再导出，避免空白图
    setTimeout(exportCanvas, 80)
  })
})
